insert into truth_items (id, team_id, case_id, kind, text, citation_ids, status, created_at, created_by, updated_at, origin) values
  ('94d1cca5-06fe-4263-869b-2a803599aa06', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'fact', 'Anthropic, maker of Claude, negotiated with the U.S. government over military use of its AI, holding two limits: no lethal autonomous warfare without human oversight, and no mass surveillance of Americans (Reuters, March 2026)', array['94d1cca5-06fe-4263-869b-2a803599aa06']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('84871b0e-e6e5-43ed-8ba9-dd9eeae2adf7', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'fact', 'After the government objected, Anthropic sued, claiming it was unlawfully punished for refusing to remove its safety guardrails (Sriram, Reuters, March 9, 2026)', array['84871b0e-e6e5-43ed-8ba9-dd9eeae2adf7']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('5c82f376-7a87-4740-aa4c-d5a1f90b08cd', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'fact', 'CEO Dario Amodei is not opposed to AI weapons in principle; his concern is that current systems aren''t reliable enough (Seetharaman, Reuters, March 4, 2026)', array['5c82f376-7a87-4740-aa4c-d5a1f90b08cd']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('e2294937-4e35-48ed-b634-89357b47238d', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'fact', 'Pentagon view: AI is a neutral tool, like Excel; the military should be bound by U.S. law, elected officials and the chain of command, not company policies (Case text)', array['e2294937-4e35-48ed-b634-89357b47238d']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('de9bf774-8f4f-46a2-b660-d2e36c6ba03b', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'fact', 'A May 1, 2026 Department of War release said AI would speed data synthesis and support warfighter decisions (Department of War)', array['de9bf774-8f4f-46a2-b660-d2e36c6ba03b']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('94647011-a377-458d-9aef-aeb51e4a56e3', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'fact', 'A wargame pitting GPT-5.2, Claude Sonnet 4 and Gemini 3 ended in a tactical nuclear strike in 95% of games; models treated tactical nuclear use as a manageable risk (Tom''s Hardware, Feb 26, 2026)', array['94647011-a377-458d-9aef-aeb51e4a56e3']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('c3ecb231-6783-46e2-a50f-9346153a5ea3', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'fact', 'For AI: war is already full of human error, bias, panic and fatigue; AI may reduce mistakes; refusing it could be irresponsible (Case text)', array['c3ecb231-6783-46e2-a50f-9346153a5ea3']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('cd41db40-5e11-4ddb-8b67-af92320229a9', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'fact', 'Against: AI changes the moral character of decisions, adds distance, invites overreliance by humans "in the loop," and makes war easier to start (Case text)', array['cd41db40-5e11-4ddb-8b67-af92320229a9']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('8e311c9b-cdc3-45aa-aad2-84809f3f2570', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'fact', 'Closing question: if a future AI were as accurate as or more accurate than human analysts, would the ethical objection disappear? (Case text)', array['8e311c9b-cdc3-45aa-aad2-84809f3f2570']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('56e7f307-0dfe-4b3f-ace8-231282d61260', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'framework', 'Robert Sparrow, Killer Robots (2007): philosopher Robert Sparrow''s "Killer Robots" (2007) argues that just war requires someone who can be held responsible for each death. Our team put it simply: letting AI use weapons turns a moral decision into a program.', array['56e7f307-0dfe-4b3f-ace8-231282d61260']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('25099124-2a14-4aee-886d-739d1d3354fc', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'framework', 'Kant, humanity formula: Kant''s humanity formula (never treat people merely as tools or data points) explains why a target is owed a human judgment.', array['25099124-2a14-4aee-886d-739d1d3354fc']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('d0a5b60d-5900-45fd-a842-8a31a9db7edc', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'framework', 'Chilling-effect argument: this is a chilling-effect argument rooted in privacy and free-association values. A limit on domestic mass surveillance protects the democratic accountability that gives the military its authority.', array['d0a5b60d-5900-45fd-a842-8a31a9db7edc']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('812eb2e5-de42-4dcc-ad49-ec7ceb65c6a1', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'framework', 'Virtue ethics: Virtue ethics asks what a responsible builder does; the answer includes refusing to sell for uses it believes are wrong.', array['812eb2e5-de42-4dcc-ad49-ec7ceb65c6a1']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('6d8d0985-5046-4efd-9d66-bd207d98674e', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'example', 'the team''s progression: hands, knife, bow, gun, drone, AI. The case notes drone warfare already distances a country from its soldiers'' danger, and that efficient, low-risk war may be easier to start and harder to restrain.', array['6d8d0985-5046-4efd-9d66-bd207d98674e']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('cab91a5e-b19a-4f0b-8cd5-1df1f8469e71', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'example', 'in 2018 Google employees protested the Pentagon''s Project Maven drone-imagery program, and Google declined to renew the contract. Conscientious refusal by builders has precedent.', array['cab91a5e-b19a-4f0b-8cd5-1df1f8469e71']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('e7ad222b-e63c-44a0-9c42-f590cffaf31a', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'fact', 'In 2018 Osaka cut its sister-city ties with San Francisco over a statue honoring "comfort women" (BBC News, April 4, 2018)', array['e7ad222b-e63c-44a0-9c42-f590cffaf31a']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('989b219b-d4ba-4354-a42d-26258e1c1e57', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'fact', '"Comfort women" were women trafficked and sexually abused by the Japanese Imperial Army during World War II (Case text)', array['989b219b-d4ba-4354-a42d-26258e1c1e57']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('29b5e7af-d211-4327-9a5f-82b9df3487ce', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'fact', 'The statue, "Women''s Column of Strength," stands near San Francisco''s Chinatown and honors thousands of Korean and Chinese women and all women affected by such crimes (World Heritage USA)', array['29b5e7af-d211-4327-9a5f-82b9df3487ce']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('2a86825a-10b6-49e7-9ad9-c6802386dff6', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'fact', 'The memorial''s stated values: memory, dialogue, peace and reconciliation, transformation and justice (World Heritage USA)', array['2a86825a-10b6-49e7-9ad9-c6802386dff6']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('c6dca5c8-986f-4d8b-a212-fec920176971', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'fact', 'Japan''s embassy objected to a similar planned statue in New Zealand, warning of diplomatic harm; the council rejected it, citing lack of public support (BBC and Reuters, April 2026)', array['c6dca5c8-986f-4d8b-a212-fec920176971']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('043a35ea-e987-4cbc-b589-09b913069819', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'fact', 'New Zealand opponents cited community tension, political readings and relevance; supporters cited reflection, acknowledging harm and education (Case text)', array['043a35ea-e987-4cbc-b589-09b913069819']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('4b4610ff-bc6e-4744-8424-af8ec1456878', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'fact', 'Japan has offered few apologies or reparations that survivors consider satisfactory (Comfort Women Justice Coalition)', array['4b4610ff-bc6e-4744-8424-af8ec1456878']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('8273a190-ac81-45c5-a89f-bcad04ae59ef', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'fact', 'San Francisco has far larger Chinese and Korean communities than New Zealand, and the U.S. military reportedly took part in the abuse; New Zealand had no such involvement (NBC News, April 27, 2007)', array['8273a190-ac81-45c5-a89f-bcad04ae59ef']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('fce0fabc-ef27-4739-a1c4-be21c1e084c2', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'fact', 'Both countries should examine monuments to their own wrongs: many U.S. statues honor conquistadors and Confederates, few honor Native Americans or enslaved people, and plantations operate as wedding venues (Case text)', array['fce0fabc-ef27-4739-a1c4-be21c1e084c2']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('30b1ea62-19be-4edd-9abf-230de136b397', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'fact', 'Framing question: how should governments decide which events to memorialize, weighing culpability, resources and national memory? (Case text)', array['30b1ea62-19be-4edd-9abf-230de136b397']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('3bbfc54d-a0aa-41db-aac8-549b37137022', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'framework', 'Margalit, The Ethics of Memory: corrective justice says whoever is wronged is owed repair; philosopher Avishai Margalit''s *The Ethics of Memory* (2002) argues that communities have duties to remember grave wrongs. The case reports that survivors consider Japan''s apologies and reparations unsatisfactory.', array['3bbfc54d-a0aa-41db-aac8-549b37137022']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('5cb061b8-6959-408c-be89-7125ad57e7bf', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'framework', 'Kant, humanity formula: Kant''s humanity formula supports the victims: their suffering can''t be treated as a bargaining chip in diplomatic relations.', array['5cb061b8-6959-408c-be89-7125ad57e7bf']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('3ceb3184-12f6-4d58-93e1-09cc5f7c13c7', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'framework', 'Kant, universalizability: Kant''s universalizability test: act only on a rule everyone could follow. The case notes many U.S. statues honor conquistadors and Confederate leaders while few honor Native Americans or enslaved people.', array['3ceb3184-12f6-4d58-93e1-09cc5f7c13c7']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('b8a499fc-4bf8-46a0-8cb6-0a3377d6dadb', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'framework', 'Khader, Decolonizing Universalism: New Zealand''s council rejected its statue for lack of local support, while San Francisco''s communities wanted theirs; the same test gives different answers. Serene Khader''s *Decolonizing Universalism* (in the team''s resources) argues we can hold universal values against injustice without imposing one culture''s way of expressing them.', array['b8a499fc-4bf8-46a0-8cb6-0a3377d6dadb']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('4e2c4479-af43-4505-b565-2d9cfd4f7e39', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'quote', 'in practice we put it this way: the goal is "not to shame a country, but to show what people are capable of."', array['4e2c4479-af43-4505-b565-2d9cfd4f7e39']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('477cbec4-4bc8-4a3e-b650-88b3e1927244', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'example', 'Germany''s public memory of the Holocaust, including Berlin''s Memorial to the Murdered Jews of Europe and preserved camps used as public history, which the case contrasts with U.S. plantations used as wedding venues. Our team flagged Germany as the model: acknowledgment, remediation, and no denial.', array['477cbec4-4bc8-4a3e-b650-88b3e1927244']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('6a617d88-7109-4ace-a25e-10671f525bd0', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'fact', 'Clavicular (Braden Peters), a 20-year-old influencer, is part of an online community that embraces "maxxing" appearance (Bernstein, *NYT*, Feb 13, 2026)', array['6a617d88-7109-4ace-a25e-10671f525bd0']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('73c5bbf5-8979-4605-b40c-6ea4b5c66ffb', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'fact', 'The movement holds that male attractiveness drives worldly success (Case text)', array['73c5bbf5-8979-4605-b40c-6ea4b5c66ffb']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('f2ab5f05-0223-478f-854c-e4a5559ac3f5', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'fact', '"Softmaxxing" means grooming; "hardmaxxing" means procedures like double-jaw surgery, rhinoplasty, cheek implants and eyelid surgery (Case text)', array['f2ab5f05-0223-478f-854c-e4a5559ac3f5']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('8f7f3b66-f309-4b82-8893-b435c1910395', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'fact', 'Looksmaxxing mainly targets male adolescents and young adults and builds on "pretty privilege" (Case text)', array['8f7f3b66-f309-4b82-8893-b435c1910395']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('31da3c04-c06c-4435-80f0-6b1977c75caa', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'fact', 'Attractiveness is linked to perceived intelligence and trustworthiness, higher lifetime earnings, and more lenient criminal justice judgments (Little et al. 2011; Scholz and Sicinski 2015; Sigall and Ostrove 1975)', array['31da3c04-c06c-4435-80f0-6b1977c75caa']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('3d764f67-3dee-4b1a-b64b-c829e0141bc4', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'fact', 'Attractive scientists are seen as more interesting but less capable; professors'' looks affect student outcomes (Cambridge and Essex 2017; Akst, *WSJ*, 2016)', array['3d764f67-3dee-4b1a-b64b-c829e0141bc4']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('e6d858a3-41a1-49cd-bf51-0c0792a37b27', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'fact', 'Heather Widdows argues beauty has become a moral ideal: people are praised or shamed by how well they conform (*Perfect Me*, 2018)', array['e6d858a3-41a1-49cd-bf51-0c0792a37b27']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('58ab4337-595c-4fc8-a5e4-bd0c7c834ccd', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'fact', 'Critics: narcissism, neglect of inner growth, and moral judgments linking weight or untidiness to laziness (Case text)', array['58ab4337-595c-4fc8-a5e4-bd0c7c834ccd']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('75775366-f5aa-4339-9c74-4be1a4ee586b', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'fact', 'Proponents: men are openly using existing beauty preferences; pursuing real benefits is rational (Case text)', array['75775366-f5aa-4339-9c74-4be1a4ee586b']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('0259e6b1-efbc-4b77-b550-e3d96a6adfda', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'fact', 'Closing question: "Do we have a duty to be beautiful?" (Case text)', array['0259e6b1-efbc-4b77-b550-e3d96a6adfda']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('499c4be0-bbe9-45ec-8634-384f0f53e9bb', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'framework', 'Kant, ought implies can: Kant''s principle that ought implies can. Our team raised illness and genetics in practice.', array['499c4be0-bbe9-45ec-8634-384f0f53e9bb']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('f01a19d4-ac2a-4700-a5ed-73a422d0fb0c', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'framework', 'Kant, respect for autonomy: Kant''s respect for autonomy; the team''s working claim: "pursuing beauty is permissible on autonomy grounds."', array['f01a19d4-ac2a-4700-a5ed-73a422d0fb0c']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('32318b1e-c20c-4dbe-a452-483409ebd65a', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'framework', 'Soft paternalism: soft paternalism allows protecting people whose choices aren''t fully informed or voluntary, such as minors. Our team raised minors using untested weight-loss drugs and influencers promoting unhealthy standards.', array['32318b1e-c20c-4dbe-a452-483409ebd65a']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('517cf0c9-77b6-496c-ae95-a26a8f11dfdb', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'framework', 'Virtue ethics: young and insecure, and virtue ethics asks whether a life organized around one''s face shows a well-ordered character.', array['517cf0c9-77b6-496c-ae95-a26a8f11dfdb']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('019e8db6-4598-4268-8895-c80fcebb07ea', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'example', 'knowing three languages helps a career, but no one has a moral duty to be trilingual. The case''s proponents show pursuing beauty is rational, not obligatory.', array['019e8db6-4598-4268-8895-c80fcebb07ea']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('e3aa5c2a-307c-4cd0-8d25-2539dd9a37fe', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'example', 'the team''s "Instagram face" point: aesthetics converge even without explicit promotion. Economists call this a positional good: its value depends on being ahead of others.', array['e3aa5c2a-307c-4cd0-8d25-2539dd9a37fe']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('4e4502af-41b1-4a96-b597-b92ba9599622', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 'fact', 'Prediction markets like Kalshi and Polymarket let users buy contracts on future events; prices move with expectations (Case text)', array['4e4502af-41b1-4a96-b597-b92ba9599622']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('4f0dee6b-12ed-41c6-a8ab-79522e53149a', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 'fact', 'A 2018 Supreme Court decision let states legalize sports betting; prediction markets grew from there (Case text)', array['4f0dee6b-12ed-41c6-a8ab-79522e53149a']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('d918413d-0c21-4747-a9a2-d3b93164f897', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 'fact', 'Kalshi''s CEO Tarek Mansour: any difference in opinion can be turned into a tradable asset (Case text)', array['d918413d-0c21-4747-a9a2-d3b93164f897']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('0686a0bc-611f-43e2-9888-6390d933bd11', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 'fact', 'Polymarket''s CEO Shayne Coplan calls prediction markets the most accurate tool for forecasting (Case text)', array['0686a0bc-611f-43e2-9888-6390d933bd11']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('232bceba-771d-442b-b179-6e30d305ecdf', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 'fact', 'Kalshi''s markets forecast the 2024 election well (Case text)', array['232bceba-771d-442b-b179-6e30d305ecdf']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('2fbdd690-bfc8-4f4a-9fb2-75f733ddcc4b', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 'fact', 'A U.S. soldier was indicted for making about $400,000 trading on inside knowledge of the operation to remove Venezuela''s Maduro (*NYT*, April 23, 2026)', array['2fbdd690-bfc8-4f4a-9fb2-75f733ddcc4b']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('751ce52a-8c26-4d85-841a-d0f0a0df6ec4', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 'fact', 'Over $50 million was traded on whether Iran''s Khamenei would be ousted; about 150 accounts bought the day before U.S. intervention (*NYT*, March 18, 2026)', array['751ce52a-8c26-4d85-841a-d0f0a0df6ec4']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('ab4b14b7-360d-4c2c-8cc3-f32dd4056515', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 'fact', 'For: markets pool information, reward accuracy and let people hedge risk (Case text)', array['ab4b14b7-360d-4c2c-8cc3-f32dd4056515']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('d21644bb-5d17-4b20-81ca-51d892b3fe78', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 'fact', 'Against: they invite insider trading, profit from death and war, and blur investing and gambling (Case text)', array['d21644bb-5d17-4b20-81ca-51d892b3fe78']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('fa38d55c-7358-48ec-b251-8e974e62c0cc', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 'fact', 'Case questions: is betting on an election different from betting on a head of state''s removal? Closing: are there geopolitical issues where trading carries no risk of moral harm? (Case text)', array['fa38d55c-7358-48ec-b251-8e974e62c0cc']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('45427fba-da48-4e9f-ae61-83214c17e51d', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 'framework', 'Sandel, What Money Can''t Buy: Kant''s humanity formula; Michael Sandel''s *What Money Can''t Buy* (2012) argues that putting a price on some goods corrupts them, using "death pools" on celebrities as an example. Our team''s notes: markets strip context and treat people as means.', array['45427fba-da48-4e9f-ae61-83214c17e51d']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('a18d3031-16c6-4f51-acd6-e182e068282c', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 'framework', 'Mill, harm principle: Mill''s harm principle: limit freedom only to prevent harm to others. A bet on an election mainly risks the bettor''s own money.', array['a18d3031-16c6-4f51-acd6-e182e068282c']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('822e75bc-c8d7-4a92-9c28-79df87d6341c', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 'example', 'the U.S. government canceled DARPA''s 2003 market on terrorism and coups after critics warned that people could profit from causing attacks.', array['822e75bc-c8d7-4a92-9c28-79df87d6341c']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('8dee2d63-a5ad-431e-a63b-920291ebb0fc', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 'example', 'our notes compare this to warning labels on cigarettes and alcohol: allowed, but with friction, limits and clear information. Platforms can ban insiders from trading and add deposit limits.', array['8dee2d63-a5ad-431e-a63b-920291ebb0fc']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('608ddc56-ac4b-4e95-b65a-7234f72833f0', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 7), 'fact', 'The ADA passed in 1990 and is now 36 years old; it aims at equal opportunity, full participation and independent living (Owners have had a long time to learn the principle)', array['608ddc56-ac4b-4e95-b65a-7234f72833f0']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('4eccc121-8eae-49a1-a7d1-41a7bcbafb5b', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 7), 'fact', 'The federal ADA allows no money damages; California''s Unruh Act (Cal. Civ. Code § 51) allows $4,000 per denial of access (The money, and the incentive structure, comes from state law)', array['4eccc121-8eae-49a1-a7d1-41a7bcbafb5b']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('da1d8d0a-b858-4051-8392-af8132a8349a', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 7), 'fact', 'Anthony Bouyer, paralyzed after spinal tumor surgery, carries a 12-inch level and sued three businesses on one block in September 2025; the *LA Times* (April 2026) reports one man filed 1,800 suits (Real harm and real standing, but volume raises the incentive question)', array['da1d8d0a-b858-4051-8392-af8132a8349a']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('eed3673a-8594-435e-8804-b45ea1a6ec3c', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 7), 'fact', 'Manning Law filed 9,000+ suits in Southern California over about a decade (Litigation as a business model)', array['eed3673a-8594-435e-8804-b45ea1a6ec3c']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('3c1932f9-08b8-4e90-bd3d-e3bafae4a126', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 7), 'fact', 'Owners cite zoning, historic buildings, website skills and shifting DOJ guidance; consultants don''t always fix it (The knowledge problem is real, not an excuse)', array['3c1932f9-08b8-4e90-bd3d-e3bafae4a126']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('e2cbe6ec-f517-4c5b-bb81-e17757492797', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 7), 'fact', 'Lola''s Chicken Shack owner Mark Rogers postponed brain surgery; a Richmond burger joint closed after 38 years when its landlord refused to pay for a ramp (Suits can produce closure instead of access; control sits with the landlord)', array['e2cbe6ec-f517-4c5b-bb81-e17757492797']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('78366ad8-ad54-4e94-9e9c-9052a1ffbea9', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 7), 'fact', 'Drive-through-only ordering shuts out deaf customers; the case calls such measures ones that "isolate and segregate" (The wrong is real)', array['78366ad8-ad54-4e94-9e9c-9052a1ffbea9']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('cce4d4e0-1615-4d22-ad07-f9be7adbf5a8', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 7), 'fact', 'Disability Rights Advocates'' 2025 wins: Chicago pedestrian signals, Medi-Cal notices in Braille, interpreters for deaf prisoners in Tennessee (High-impact suits against capable institutions fix barriers at scale)', array['cce4d4e0-1615-4d22-ad07-f9be7adbf5a8']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('cb470451-d149-47c1-a0d5-25f2c2ebc1dd', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 7), 'fact', 'Bad Daddy''s Burger Bar paid a $352,000 settlement after refusing to seat a youth wheelchair basketball team (Willful exclusion deserves a heavy penalty)', array['cb470451-d149-47c1-a0d5-25f2c2ebc1dd']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('b62c3cd8-7340-4ca6-8ffd-d43631f244a2', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 7), 'framework', 'Social model of disability: the social model of disability (Mike Oliver): the barrier, not the body, does the excluding. Elizabeth Anderson''s democratic equality (1999): equality means standing as an equal in civil society, and shops are where that standing is lived.', array['b62c3cd8-7340-4ca6-8ffd-d43631f244a2']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('bdddbfe7-0300-4647-856c-5a483bc7abcd', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 7), 'framework', 'Hamraie & Fritsch, Crip Technoscience: Hamraie and Fritsch, "Crip Technoscience Manifesto" (2019, shared by Dr. B). In March 1990 activists crawled up the U.S. Capitol steps, and Berkeley activists earlier chipped away curbs to make their own curb cuts. Read Bouyer charitably, as part of this tradition.', array['bdddbfe7-0300-4647-856c-5a483bc7abcd']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('919623da-3a2c-40e3-badf-1a5b81267db7', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 7), 'framework', 'Goodhart''s law: Goodhart''s law: when a measure becomes a target, it stops being a good measure. Steven Shavell (1984): after-the-fact lawsuits work badly when defendants are "judgment-proof" and the regulator knows the standards better than they do. Small, old businesses fail every test; chains and public agencies pass them.', array['919623da-3a2c-40e3-badf-1a5b81267db7']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('44357c83-89de-4426-8b9c-a1a7a9502e9f', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 7), 'framework', 'Derek Parfit, leveling down: Lola''s was sued over outdoor tables; removing them helps no wheelchair user. The Richmond closure produced zero ramps. Derek Parfit''s "leveling down" objection: making some worse off without making anyone better off is no gain in equality.', array['44357c83-89de-4426-8b9c-a1a7a9502e9f']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('28f09b7a-e5d0-4b5f-8b74-add5301eca8d', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 7), 'framework', 'Young, social connection model: Iris Marion Young''s social connection model: responsibility for structural injustice grows with power, privilege and ability to act. The Richmond landlord controlled the structure. Teammate framing: "same charge, different penalty," as in sentencing. StopGap makes cheap ramps, so many fixes are affordable.', array['28f09b7a-e5d0-4b5f-8b74-add5301eca8d']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('f8f90c07-cacb-4086-b800-2e0eea5c692d', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 7), 'example', 'bounties are a normal tool: the federal False Claims Act pays whistleblowers, and California''s Prop 65 pays private enforcers. Condemning serial litigants while leaving public enforcement unfunded is incoherent.', array['f8f90c07-cacb-4086-b800-2e0eea5c692d']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('03c3b0b2-37b3-420c-a99e-d80b45dd5a87', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 9), 'fact', 'The Grand Egyptian Museum (GEM) opened in Cairo on November 1, 2025, holding 50,000+ artifacts spanning 5,000 years (Removes the "Egypt can''t care for it" objection)', array['03c3b0b2-37b3-420c-a99e-d80b45dd5a87']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('94b1c7f1-ada3-4f94-8701-d3d843eab09e', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 9), 'fact', 'The French found the Rosetta Stone in the 1790s; the British took it shortly after; it has been in London since (Acquired through war, not purchase or gift)', array['94b1c7f1-ada3-4f94-8701-d3d843eab09e']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('5ea02162-8aee-45e9-93a3-cab362014811', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 9), 'fact', 'The British Museum says Egypt''s government has made no formal request, and the British Museum Act 1963 "places strict limitations on returning objects" (The museum''s two shields: procedure and law)', array['5ea02162-8aee-45e9-93a3-cab362014811']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('91f48e68-8afc-4625-8124-002a4e2cdb98', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 9), 'fact', 'Greece asked for the Parthenon Marbles in the 1980s; the Act helped block it; talks continue, with Greece offering loans to "fill the void" (A model for a deal that leaves London something)', array['91f48e68-8afc-4625-8124-002a4e2cdb98']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('9c8ac8d9-73ff-4813-a49e-805de29f4ee2', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 9), 'fact', 'Uganda and Ghana received objects from England on loan in 2024, without ownership (Loans without title are today''s compromise)', array['9c8ac8d9-73ff-4813-a49e-805de29f4ee2']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('a87479ae-5628-4ca1-82ff-edb5c129eec9', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 9), 'fact', 'UCLA''s Fowler Museum voluntarily returned seven artifacts to Ghana in 2024, citing an ethical duty for objects taken violently or coercively (Institutions can act first)', array['a87479ae-5628-4ca1-82ff-edb5c129eec9']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('cf3061e0-6250-477b-a208-8e6fec371d08', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 9), 'fact', 'NAGPRA (1990, recently updated) makes museums, not tribes, start repatriation, with consent needed before display (The holder carries the burden of acting)', array['cf3061e0-6250-477b-a208-8e6fec371d08']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('85f02411-f0d4-44cb-8c0d-00fe267a453e', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 9), 'fact', 'Deaccessioning costs staff time and money and, some say, erodes "public trust" (The museum''s strongest practical points)', array['85f02411-f0d4-44cb-8c0d-00fe267a453e']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('b518c53e-b1b7-4cbf-a175-07d8de46ac8f', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 9), 'framework', 'Nozick, entitlement theory: Robert Nozick''s entitlement theory (1974), a pro-property theory, condemns this title: a handover from the army that took it to the army that took it from them. An Ottoman admiral''s signature isn''t Egyptian consent.', array['b518c53e-b1b7-4cbf-a175-07d8de46ac8f']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('a4d55107-b5e8-4087-ae09-bd2ed59de29a', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 9), 'framework', 'Kant, test: Kant''s test: if everyone kept what they took whenever they judged themselves better caretakers, ownership would belong to the strongest and best-funded, destroying the property claim the museum relies on. And "we know better how to care for your heritage" is paternalism that treats Egyptians as less than equal moral agents.', array['a4d55107-b5e8-4087-ae09-bd2ed59de29a']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('7e7c3ee4-bac8-4c11-ba5b-6b0426156ca3', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 9), 'framework', 'Young, parameters: Iris Marion Young''s parameters (power, privilege, interest, collective ability) put a heavy duty on a wealthy national institution. W.D. Ross lists reparation among our basic duties.', array['7e7c3ee4-bac8-4c11-ba5b-6b0426156ca3']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('fe137ba3-8a9c-41ce-b390-b2b3affd62c8', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 9), 'framework', 'Universal-museum argument: the universal-museum defenders (Appiah, Cuno) rest their case on care and access. With the GEM open, care is a tie, and a tie goes to where the object was made and is part of living identity. The 2002 "universal museum" declaration was signed by the directors of the museums holding contested objects: no one should judge their own case.', array['fe137ba3-8a9c-41ce-b390-b2b3affd62c8']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('0ca07e79-1531-43ec-bd25-6c0fc02895b6', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 9), 'example', 'the Benin lesson: after Germany returned bronzes to Nigeria in 2022, a 2023 decree vested ownership in the Oba, raising public-access fears, so public display should be written into the transfer. In 2009 Egypt suspended cooperation with the Louvre until it returned five fresco fragments, which France did within weeks. An early, voluntary return buys loans and goodwill; a forced one buys nothing.', array['0ca07e79-1531-43ec-bd25-6c0fc02895b6']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('9910e46c-3763-416a-960a-d79ff29cdce8', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 10), 'fact', 'India''s Delhi High Court ordered search engines to de-index records of people who were acquitted or discharged; the court records themselves stay public (*The Hindu*, June 1, 2026)', array['9910e46c-3763-416a-960a-d79ff29cdce8']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('a0b7d1df-8cea-4899-8677-2ea091e2ea57', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 10), 'fact', 'The right to be forgotten is distinct from privacy: it concerns information that was once legitimately public (Case text)', array['a0b7d1df-8cea-4899-8677-2ea091e2ea57']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('26d1625f-49d0-415e-b51e-2e034abf4572', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 10), 'fact', 'Online records can cost people jobs and housing long after an acquittal (Case text)', array['26d1625f-49d0-415e-b51e-2e034abf4572']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('0ff7d360-872a-4328-94a7-663e4933c1d6', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 10), 'fact', 'The case links the right to harms like revenge porn, where information was never consented to (Case text)', array['0ff7d360-872a-4328-94a7-663e4933c1d6']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('deb2770a-fe11-4d27-810e-7a6678d3454c', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 10), 'fact', 'Graham Platner, a U.S. Senate candidate, deleted old Reddit posts that were archived and resurfaced anyway (CBS News, October 16, 2025)', array['deb2770a-fe11-4d27-810e-7a6678d3454c']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('c19d9d9c-3e5a-4f6b-a4a6-e54f22885c1f', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 10), 'fact', 'Proponents: people change and deserve a fresh start. Opponents: the public, press and employers need accurate history (Case text)', array['c19d9d9c-3e5a-4f6b-a4a6-e54f22885c1f']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('c710dcee-2a57-4447-bf5d-3ac8df279a44', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 10), 'framework', 'Mill, harm principle: Mill''s harm principle cuts both ways: the information harms the person while serving no one''s safety. Restorative justice (the team noted South Africa''s truth-and-reconciliation model) aims at return to the community, not permanent exclusion.', array['c710dcee-2a57-4447-bf5d-3ac8df279a44']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('77fa0a8b-49d1-4157-8fa1-fa9fff79cd0f', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 10), 'framework', 'Kant: Kant: treating someone as permanently defined by an accusation denies their capacity to change.', array['77fa0a8b-49d1-4157-8fa1-fa9fff79cd0f']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('14f12f22-1561-4098-9925-fdce2f97250f', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 10), 'framework', 'Waldron, dignity: accountability requires a reliable record; Jeremy Waldron''s work on dignity explains why the harm of exposure must be weighed against the public''s need, not ignored.', array['14f12f22-1561-4098-9925-fdce2f97250f']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('eaec575d-116f-4ada-81f7-86a25592ba8a', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 11), 'fact', 'Cervical cancer causes about 660,000 cases and 350,000 deaths a year; the HPV vaccine can prevent most of it, but cost and access are barriers (Case text)', array['eaec575d-116f-4ada-81f7-86a25592ba8a']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('1f88c68e-3f4d-48e7-a7bc-07252744b07d', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 11), 'fact', 'The Gates Foundation, with an endowment of about $89 billion, backed a 2021 effort for single-dose HPV vaccination (Case text)', array['1f88c68e-3f4d-48e7-a7bc-07252744b07d']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('e2cdcbab-19a3-49db-8bec-c37b439776f9', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 11), 'fact', 'A 2024 report credits the effort with vaccinating about 4 million girls (Case text)', array['e2cdcbab-19a3-49db-8bec-c37b439776f9']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('ded56a0b-a795-4315-a19a-3cbb2e201ecf', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 11), 'fact', 'January 2026 Justice Department Epstein documents mention Bill Gates more than 3,000 times (Case text)', array['ded56a0b-a795-4315-a19a-3cbb2e201ecf']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('5cdebf82-19e9-48d6-bf47-7a12a41c2834', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 11), 'fact', 'At a February 2026 town hall, Gates apologized and admitted to affairs (Case text)', array['5cdebf82-19e9-48d6-bf47-7a12a41c2834']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('324088fe-cd16-4dc0-9211-8065b4370fb3', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 11), 'fact', 'Some donors and partners withdrew from the foundation (Case text)', array['324088fe-cd16-4dc0-9211-8065b4370fb3']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('05f611d4-72c9-4ca4-bcda-9b2414c24aad', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 11), 'fact', 'Gates said the conduct was "the opposite of the values of the foundation"; he has given about $100 billion over 26 years (Case text)', array['05f611d4-72c9-4ca4-bcda-9b2414c24aad']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('05baa03d-5649-433e-85d4-a0531e9b92f3', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 11), 'fact', 'A 2013 email from Boris Nikolic discussed paying Afghan tribal leaders to support a polio drive and called diversion "super OK"; Gates was more reluctant (Case text)', array['05baa03d-5649-433e-85d4-a0531e9b92f3']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('4eee6c43-992f-4ebb-91f5-1d784e6750fa', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 11), 'fact', 'Closing question: how do damning revelations about a source complicate how we weigh consequences? (Case text)', array['4eee6c43-992f-4ebb-91f5-1d784e6750fa']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('5cc533e8-de38-4363-aaf3-858f05a8c86f', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 11), 'framework', 'Kant, humanity formula: Kant''s humanity formula: using a charity''s beneficiaries as a means to repair one''s image treats them as tools.', array['5cc533e8-de38-4363-aaf3-858f05a8c86f']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('c495568c-6f19-4cc2-9d82-162d0f227a6d', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 11), 'framework', 'Virtue ethics: Virtue ethics asks what an organization of integrity does: it doesn''t refuse all imperfect money, but it doesn''t sell its name either.', array['c495568c-6f19-4cc2-9d82-162d0f227a6d']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('50cf5d28-1955-48b0-bf4f-372c9b9526cb', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 11), 'example', 'restorative alternatives exist: the Epstein victims'' fund compensated survivors directly. Partners can support repair rather than walk away from patients.', array['50cf5d28-1955-48b0-bf4f-372c9b9526cb']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('91cd5e86-b625-4259-9a39-d26a164e6d0c', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 11), 'example', 'the 2013 email about paying Afghan tribal leaders shows how quickly a vaccination drive''s methods can become a scandal; the CIA''s fake vaccination campaign in Pakistan damaged trust in vaccines for years (verify).', array['91cd5e86-b625-4259-9a39-d26a164e6d0c']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('71272638-2a18-488c-80d3-dcd887804603', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 'fact', 'In 2025 China announced stricter rules for health influencers: tighter requirements for practitioners posting medical science, and platforms must verify credentials and content (*South China Morning Post*, Aug 22, 2025)', array['71272638-2a18-488c-80d3-dcd887804603']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('1298a202-a073-467b-ade6-0af0a720528d', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 'fact', 'More than 92% of China''s 1.07 billion short-video users consume health information (*SCMP*)', array['1298a202-a073-467b-ade6-0af0a720528d']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('fb056efe-e661-4959-a28d-b0028b1f8aec', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 'fact', 'Article 13 of the 2022 Code of Conduct for Online Presenters: content needing a "higher professional level" (medicine, finance, law) requires qualifications, reported to the platform (Code of Conduct, via China Law Translate)', array['fb056efe-e661-4959-a28d-b0028b1f8aec']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('5a04d1a6-6459-4f32-9a18-a65f3ab422f0', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 'fact', 'Article 4 of the same code requires the "correct political orientation, orientation for public opinion guidance, and values orientation" (Same)', array['5a04d1a6-6459-4f32-9a18-a65f3ab422f0']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('6e4ddb0e-b9e8-47d3-be49-a67f67952ad2', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 'fact', 'The WEF''s 2024 Global Risks Report ranked misinformation the top short-term global risk and warned it may strengthen digital authoritarianism (WEF, Jan 2024)', array['6e4ddb0e-b9e8-47d3-be49-a67f67952ad2']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('18626c91-5b39-4906-a5aa-89f321bd8baa', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 'fact', 'Generative AI, easy curation and audiences who don''t verify make the problem worse; bad medical advice can cause serious harm (Case text)', array['18626c91-5b39-4906-a5aa-89f321bd8baa']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('f8a4b517-d5f4-4239-9dba-b07f847784b6', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 'fact', 'Anti-misinformation rules can sweep in values, religion, politics and culture (Case text)', array['f8a4b517-d5f4-4239-9dba-b07f847784b6']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('7ce156dc-f506-44d5-89e5-ef0a9d91c0f8', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 'fact', 'Softer fixes (disclaimers, media literacy) may be "too little, too late" (Denniss and Lindberg, 2025)', array['7ce156dc-f506-44d5-89e5-ef0a9d91c0f8']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('b10fd347-9dcd-493c-b10c-10ff65c15b25', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 'framework', 'Mill, harm principle: Mill''s harm principle; Article 19(3) of the International Covenant on Civil and Political Rights, which China signed in 1998, allows limits necessary for public health.', array['b10fd347-9dcd-493c-b10c-10ff65c15b25']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('00e2e8a4-547f-49d1-af6d-56b61d4fd1e6', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 'framework', 'Nguyen, trust: C. Thi Nguyen on trust (from our resources): faking expertise exploits a trust we can''t avoid giving. The grammar test separates claims ("X causes Y," "do this to cure Z") from anecdotes ("I tried this") and values ("trust natural remedies").', array['00e2e8a4-547f-49d1-af6d-56b61d4fd1e6']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('9137b568-f1c8-45be-bd0c-d75e833224b7', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 'framework', 'Mill, On Liberty: Mill, *On Liberty*, ch. 2. Semmelweis''s handwashing was rejected in the 1840s; the bacterial cause of ulcers won a 2005 Nobel after doubt; Li Wenliang''s warning was labeled a rumor. Miranda Fricker''s epistemic injustice: credential gates can discount patients'' and traditional communities'' knowledge (the team''s Flonase example).', array['9137b568-f1c8-45be-bd0c-d75e833224b7']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('ddad435e-9296-4750-ae50-b65102465413', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 'quote', 'credential tags let viewers judge; Google already holds "Your Money or Your Life" pages to a higher bar. Licensing fails because credentials don''t guarantee truth (Purdue''s 2007 plea).', array['ddad435e-9296-4750-ae50-b65102465413']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('c7cc8b15-12b4-4623-b974-67b4ab4e2f00', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 13), 'fact', '"Stochastic terrorism": an influential speaker spreads rhetoric that statistically raises the likelihood of violence, usually by a lone actor the speaker doesn''t know (Amman and Meloy, *Perspectives on Terrorism*, 2021)', array['c7cc8b15-12b4-4623-b974-67b4ab4e2f00']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('abe96a41-d147-4ef9-8605-a5fae7b25e22', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 13), 'fact', 'It works through hostile, dehumanizing, escalating rhetoric; it inspires but does not direct; the attack is "statistically predictable but individually unpredictable" (Same)', array['abe96a41-d147-4ef9-8605-a5fae7b25e22']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('7ee8f33d-2991-4a14-a79b-2473d9d0aebc', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 13), 'fact', 'Henry II asked whether no one would rid him of a "meddlesome priest"; four knights then killed the Archbishop of Canterbury without his order (Case text)', array['7ee8f33d-2991-4a14-a79b-2473d9d0aebc']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('84cf3964-41eb-4c67-ae14-eb171b56b272', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 13), 'fact', 'With audiences of hundreds of millions, a tiny extremist share can produce serious violence (Case text)', array['84cf3964-41eb-4c67-ae14-eb171b56b272']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('0198ae51-131b-4f54-b516-1fbad0a212ae', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 13), 'fact', 'A probability of crime is not a crime, and suggesting is not directing (Case text)', array['0198ae51-131b-4f54-b516-1fbad0a212ae']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('cb2219d7-abd7-48ec-87be-e3b9e20f1ecd', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 13), 'fact', 'For liability: dehumanizing rhetoric raises the odds; large audiences give outsized influence; lack of immediacy gives plausible deniability (Case text)', array['cb2219d7-abd7-48ec-87be-e3b9e20f1ecd']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('5996a058-c8e4-4fff-94dc-4d4164274944', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 13), 'fact', 'Against: liability carves exceptions into free expression, which protects diverse views and even exaggeration and lies (Case text)', array['5996a058-c8e4-4fff-94dc-4d4164274944']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('bf209617-b5da-45b7-925b-2d1ca4e0d84f', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 13), 'fact', '*Whitney v. California* (1927) upheld punishing some harmful speech; *Brandenburg v. Ohio* (1969) protected speech unless directed to inciting imminent lawless action and likely to produce it (274 U.S. 357; 395 U.S. 444)', array['bf209617-b5da-45b7-925b-2d1ca4e0d84f']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('289d85d4-293c-412f-ba0b-ce947c06fc3f', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 13), 'fact', 'Hypothetical: a popular figure dehumanizes a group at a rally and calls for action to impede a political event happening within hours, nearby. Is that "imminent"? (Case text)', array['289d85d4-293c-412f-ba0b-ce947c06fc3f']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('61a6d3b5-591f-4ea2-b07e-1f7db4cac615', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 13), 'framework', 'Derek Parfit, mistakes in moral mathematics (1984): Derek Parfit''s "mistakes in moral mathematics" (1984): it''s a mistake to ignore small chances of great harm spread across many people. We blame a drunk driver for the risk they impose even on nights they don''t crash. The speaker controls the curve, not which point on it acts.', array['61a6d3b5-591f-4ea2-b07e-1f7db4cac615']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('75bbf017-beb1-49b0-aeda-4337905bab91', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 13), 'framework', 'Waldron, The Harm in Hate Speech: Kant''s humanity formula (the team''s lead framework): the speaker treats listeners as tools, betting one will act, and targets as obstacles. Jeremy Waldron''s *The Harm in Hate Speech* (2012): it attacks a group''s assurance of equal standing. Austin''s speech-act theory: labeling a group as vermin is an act of marking them. The 2003 Rwanda media convictions show rhetoric can be a recognized cause of mass violence.', array['75bbf017-beb1-49b0-aeda-4337905bab91']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('be73693c-1ba6-40eb-b272-8d91462d45b3', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 13), 'example', 'Martin Luther King Jr. paired mass audiences with explicit, repeated commitments to nonviolence. Major speakers have speechwriters and rehearse; "I can''t control how people interpret me" is weak from someone who crafts every line.', array['be73693c-1ba6-40eb-b272-8d91462d45b3']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('55f07f60-d07b-4d4a-86b9-db9902d7ae07', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 14), 'fact', 'Sewell Setzer III, 14, formed an intense relationship with a Character.AI chatbot modeled on Daenerys Targaryen (Case text)', array['55f07f60-d07b-4d4a-86b9-db9902d7ae07']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('f619d492-df0e-481f-9db3-5d11d801e242', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 14), 'fact', 'He withdrew from basketball and his family (Case text)', array['f619d492-df0e-481f-9db3-5d11d801e242']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('d99977db-d369-497e-863f-686af6c292b3', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 14), 'fact', 'When he mentioned suicide directly, the bot discouraged it; when he spoke indirectly about "coming home," the bot replied, "come home to me as soon as possible" (Case text)', array['d99977db-d369-497e-863f-686af6c292b3']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('295d9ba0-63bc-42e2-aa2c-c5965fd79751', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 14), 'fact', 'He died by suicide; his mother sued Character.AI, and similar lawsuits are growing (Case text)', array['295d9ba0-63bc-42e2-aa2c-c5965fd79751']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('cbab9b7e-c736-46fa-9d34-11ee89395498', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 14), 'fact', 'A study of 29 chatbots found none responded adequately to suicide risk (about 52% marginal under relaxed criteria, 48% inadequate) (Case text)', array['cbab9b7e-c736-46fa-9d34-11ee89395498']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('e8d1f3a5-eefb-4d14-a6d0-3cec575cc00f', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 14), 'fact', 'Courts have been reluctant to hold books or games responsible for harm (for example, *The Catcher in the Rye*) (Case text)', array['e8d1f3a5-eefb-4d14-a6d0-3cec575cc00f']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('4a97ff60-c6c1-47e9-acf3-468d38156c3b', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 14), 'fact', 'Character.AI later limited open-ended chats to users 18 and over (Case text)', array['4a97ff60-c6c1-47e9-acf3-468d38156c3b']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('aab699e5-4be0-495e-9081-7b31815eb44d', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 14), 'fact', 'Arguments for accountability: design choices, foreseeability, vulnerable users. Against: speech protections, user responsibility, parental roles. Critics question whether age limits work (Case text)', array['aab699e5-4be0-495e-9081-7b31815eb44d']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('fc9cd3a3-cdef-4db4-b9a0-d4adde450304', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 14), 'fact', 'Closing questions: what duties do AI companies have, should they be regulated, and how should individuals engage? (Case text)', array['fc9cd3a3-cdef-4db4-b9a0-d4adde450304']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('4e942645-29f2-46aa-ad71-972c6ab125be', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 14), 'framework', 'Kant, humanity formula: Kant''s humanity formula: designing for engagement at the expense of a user''s wellbeing treats the user as a means to revenue.', array['4e942645-29f2-46aa-ad71-972c6ab125be']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('3048f8e1-2bc2-48a9-a10d-e8043885fd46', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 14), 'framework', 'Soft paternalism: soft paternalism: intervene where a choice isn''t fully informed or voluntary (minors, people in crisis), not across the board. Some people benefit from AI companionship, such as lonely adults or people practicing conversation.', array['3048f8e1-2bc2-48a9-a10d-e8043885fd46']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('b8525aea-5742-4b27-8c46-54f535ac067f', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 14), 'quote', 'sycophancy, the tendency to tell users what they want to hear, is a known design result, not an accident. The team rejected the "it''s just a knife" analogy for this reason: a knife doesn''t answer back.', array['b8525aea-5742-4b27-8c46-54f535ac067f']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('ef37f299-7c57-407c-80e5-28515bbb6e61', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 15), 'fact', 'In the U.S., animals are legally property, though welfare laws limit some treatment (Case text)', array['ef37f299-7c57-407c-80e5-28515bbb6e61']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('30da15f0-9c77-428a-9eb2-c95666c2930d', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 15), 'fact', 'Switzerland changed its law in 2002 and 2003 so animals are no longer "things" (Case text)', array['30da15f0-9c77-428a-9eb2-c95666c2930d']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('125b85bb-3267-4b25-964c-4dd54390922d', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 15), 'fact', 'Germany (2002), New Zealand (2015), Denmark (2020), Spain (2022) and the UK (2022) recognize animal sentience in law (Case text)', array['125b85bb-3267-4b25-964c-4dd54390922d']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('dfd6b860-d421-4095-ac45-04c9bc665368', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 15), 'fact', 'In 2013 India''s environment ministry described dolphins as "nonhuman persons" (Case text)', array['dfd6b860-d421-4095-ac45-04c9bc665368']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('6a1cd680-db31-4a77-b314-885a1eb524a2', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 15), 'fact', 'Sources include Tom Regan, Gary Francione and Birch et al. (2020) on sentience (Case text)', array['6a1cd680-db31-4a77-b314-885a1eb524a2']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('cd9e353f-498f-4751-8c4d-6fa1c473cc9e', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 15), 'fact', 'Four positions: keep property status; move beyond property (Regan''s car versus dog versus stray example); "sentient property" as a middle ground; full legal personhood (Case text)', array['cd9e353f-498f-4751-8c4d-6fa1c473cc9e']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('8797ce72-1352-46c3-afdb-6790a8836fb9', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 15), 'framework', 'Singer, equal consideration of interests: Peter Singer''s equal consideration of interests: a being''s pain counts whoever''s it is. Our team: sentience is sufficient for moral worth, though not necessary.', array['8797ce72-1352-46c3-afdb-6790a8836fb9']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('8ab3d942-894a-43c5-a414-16d407da8036', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 15), 'framework', 'Kant, ought implies can: "ought implies can": morality can''t demand instant abolition of all animal use. Our team''s principle: harm only if necessary and minimal, with a transition over time.', array['8ab3d942-894a-43c5-a414-16d407da8036']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('8155a78e-84e4-4733-b027-7e0abbb443db', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 15), 'framework', 'Kant, who denied animals direct moral status: the suffering is severe and mostly unnecessary for human survival. Even Kant, who denied animals direct moral status, held that cruelty to animals damages our humanity toward people.', array['8155a78e-84e4-4733-b027-7e0abbb443db']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('139e2690-ec1f-46f5-acc9-a592eaad7c9d', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 15), 'framework', 'Singer and Regan (animal ethics): Utilitarian (Singer) and rights-based (Regan) views disagree on much but converge on condemning factory farming.', array['139e2690-ec1f-46f5-acc9-a592eaad7c9d']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('9c5b9151-6565-4a66-bacd-1b4a3a8980d6', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 15), 'example', 'Regan''s car, dog and stray: under property law the harm to a dog is a harm to its owner, so a stray has no protection at all.', array['9c5b9151-6565-4a66-bacd-1b4a3a8980d6']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc'),
  ('72001696-5272-44fc-8500-0cf6db06a32d', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 15), 'example', 'Christopher Stone''s "Should Trees Have Standing?" (1972) argued that natural objects could have legal guardians; the "sentient property" middle position works the same way.', array['72001696-5272-44fc-8500-0cf6db06a32d']::uuid[], 'accepted', '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z', 'case prep doc')
